validator:
function validate(input) {
  const [{ Customer = [], Product = [] }] = input;
  const products = new Set();
  for (const [key] of Product) {
    if (key === null) return 'Every product needs a product_key.';
    if (products.has(key)) return `product_key ${key} appears twice in Product.`;
    products.add(key);
  }
  for (const [customer, key] of Customer) {
    if (customer === null) return 'customer_id cannot be null.';
    if (!products.has(key)) return `Customer ${customer} bought product ${key}, which is not in Product.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const productCount = small ? Math.floor(rand() * 5) : 25;
  const Product = [];
  for (let i = 0; i < productCount; i++) Product.push([small ? 5 + i : 100 + 3 * i]);
  const Customer = [];
  if (productCount > 0) {
    const customers = small ? 1 + Math.floor(rand() * 4) : 120;
    const limit = small ? 8 : 2000;
    for (let c = 1; c <= customers && Customer.length < limit; c++) {
      const id = small ? c : 1000 + c;
      // Some customers buy the whole catalogue; the rest buy a random part of it, often with repeats.
      const buysAll = rand() < 0.4;
      for (const [key] of Product) {
        if (Customer.length >= limit) break;
        if (buysAll || rand() < 0.6) Customer.push([id, key]);
        if (Customer.length < limit && rand() < 0.25) Customer.push([id, Product[Math.floor(rand() * productCount)][0]]);
      }
    }
    // Shuffle so a customer's purchases are not stored together.
    for (let i = Customer.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [Customer[i], Customer[j]] = [Customer[j], Customer[i]];
    }
  }
  return [{ Customer, Product }];
}
